// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 sequenceNumber, bytes32 batcherHash, uint256 l1FeeOverhead, uint256 l1FeeScalar) public {
        address depositorAccount = c.depositorAccount();
        // Only depositorAccount should succeed; all other callers should revert
        vm.assume(caller != depositorAccount);
        vm.prank(caller);
        // Wrap in try/catch to capture revert
        try c.setL1BlockValues(number, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar) {
            // If it doesn't revert, the rule fails
            assertTrue(false);
        } catch {
            // Revert is expected for non-depositor
            assertTrue(true);
        }
    }
}
